// @mui
import PropTypes from 'prop-types';
import { alpha, styled } from '@mui/material/styles';
import { Card, Typography } from '@mui/material';
import moment from 'moment';
// utils
import { fShortenNumber } from '../../../utils/formatNumber';
// components
import Iconify from '../../../components/Iconify';

// ----------------------------------------------------------------------

const IconWrapperStyle = styled('div')(({ theme }) => ({
  margin: 'auto',
  display: 'flex',
  borderRadius: '50%',
  alignItems: 'center',
  width: theme.spacing(8),
  height: theme.spacing(8),
  justifyContent: 'center',
  marginBottom: theme.spacing(3),
}));

// ----------------------------------------------------------------------

AppWidgetSummary.propTypes = {
  color: PropTypes.string,
  icon: PropTypes.string,
  title: PropTypes.string.isRequired,
  total: PropTypes.number.isRequired,
  sx: PropTypes.object,
  text: PropTypes.string,
};

export default function AppWidgetSummary({ title, total, icon, color = 'primary', sx, text,  ...other }) {
  return (
    <Card
      sx={{
        py: 5,
        boxShadow: 0,
        textAlign: 'center',
        color: (theme) => theme.palette[color].darker,
        bgcolor: (theme) => theme.palette[color].lighter,
        ...sx,
      }}
      {...other}
    >
      <IconWrapperStyle
        sx={{
          color: (theme) => theme.palette[color].dark,
          // backgroundImage: (theme) =>
          //   `linear-gradient(135deg, ${alpha(theme.palette[color].dark, 0)} 0%, ${alpha(
          //     theme.palette[color].dark,
          //     0.24
          //   )} 100%)`,
        }}
        style={{backgroundImage: 'linear-gradient(135deg, rgba(12, 83, 183, 0) 0%, rgb(255 255 255 / 24%) 100%)'}}
      >
        <Iconify icon={icon} style={{color: '#FEFEFE'}} width={24} height={24} />
      </IconWrapperStyle>

      <Typography style={{color: '#FEFEFE'}} variant="h3">{fShortenNumber(total)}</Typography>

      <Typography variant="subtitle2" style={{color: '#FEFEFE'}} sx={{ opacity: 0.72 }}>
        {title} {`${moment().format('dddd, MMMM Do')}`}    
        <br/>
        <br/>
        <span style={{color: '#FEFEFE'}}>{text}</span>
      </Typography>
    </Card>
  );
}
